#include <string>
#include <unordered_map>
#include <algorithm>

class Solution {
public:
    int maxPartitionsAfterOperations(std::string s, int k) {
        if (k == 26) return 1;
        std::unordered_map<long long, int> memo;
        auto dfs = [&](auto& self, int i, int mask, bool changed) -> int {
            if (i == (int)s.size()) return 1;
            long long state = ((long long)i << 28) | ((long long)mask << 1) | (changed ? 1 : 0);
            if (memo.count(state)) return memo[state];

            int bit = 1 << (s[i] - 'a');
            int newMask = mask | bit;
            int res = 0;
            if (__builtin_popcount(newMask) > k) {
                res = 1 + self(self, i + 1, bit, changed);
            } else {
                res = self(self, i + 1, newMask, changed);
            }
            if (!changed) {
                for (int c = 0; c < 26; ++c) {
                    int cBit = 1 << c;
                    int newMask2 = mask | cBit;
                    int cand = 0;
                    if (__builtin_popcount(newMask2) > k) {
                        cand = 1 + self(self, i + 1, cBit, true);
                    } else {
                        cand = self(self, i + 1, newMask2, true);
                    }
                    res = std::max(res, cand);
                }
            }
            return memo[state] = res;
        };
        return dfs(dfs, 0, 0, false);
    }
};

import java.util.HashMap;
import java.util.Map;

class Solution {
    private Map<Long, Integer> memo;

    public int maxPartitionsAfterOperations(String s, int k) {
        if (k == 26) return 1;
        memo = new HashMap<>();
        return dfs(0, 0, false, s, k);
    }

    private int dfs(int i, int mask, boolean changed, String s, int k) {
        if (i == s.length()) return 1;
        long state = ((long) i << 28) | ((long) mask << 1) | (changed ? 1L : 0L);
        if (memo.containsKey(state)) return memo.get(state);

        int bit = 1 << (s.charAt(i) - 'a');
        int newMask = mask | bit;
        int res;
        if (Integer.bitCount(newMask) > k) {
            res = 1 + dfs(i + 1, bit, changed, s, k);
        } else {
            res = dfs(i + 1, newMask, changed, s, k);
        }

        if (!changed) {
            for (int c = 0; c < 26; c++) {
                int cBit = 1 << c;
                int newMask2 = mask | cBit;
                int cand;
                if (Integer.bitCount(newMask2) > k) {
                    cand = 1 + dfs(i + 1, cBit, true, s, k);
                } else {
                    cand = dfs(i + 1, newMask2, true, s, k);
                }
                res = Math.max(res, cand);
            }
        }
        memo.put(state, res);
        return res;
    }
}

var maxPartitionsAfterOperations = function(s, k) {
    if (k === 26) return 1;
    const memo = new Map();
    function popcount(x) {
        let cnt = 0;
        while (x > 0) { cnt += x & 1; x >>= 1; }
        return cnt;
    }
    function dfs(i, mask, changed) {
        if (i === s.length) return 1;
        const key = `${i}_${mask}_${changed ? 1 : 0}`;
        if (memo.has(key)) return memo.get(key);

        const bit = 1 << (s.charCodeAt(i) - 97);
        const newMask = mask | bit;
        let res = 0;
        if (popcount(newMask) > k) {
            res = 1 + dfs(i + 1, bit, changed);
        } else {
            res = dfs(i + 1, newMask, changed);
        }

        if (!changed) {
            for (let c = 0; c < 26; c++) {
                const cBit = 1 << c;
                const newMask2 = mask | cBit;
                let cand = 0;
                if (popcount(newMask2) > k) {
                    cand = 1 + dfs(i + 1, cBit, true);
                } else {
                    cand = dfs(i + 1, newMask2, true);
                }
                res = Math.max(res, cand);
            }
        }
        memo.set(key, res);
        return res;
    }
    return dfs(0, 0, false);
};
